(787401, 85897, 14593, '<td valign="top">different and interesting idea</td>', 'different and interesting idea', '2004-06-30 15:13:12.000000', NULL, 1),
(787408, 86103, 14593, '<td valign="top">I like the idea, but I feel the softness doesn''t convey much softness....it conveys stiffness and hardness to me.....yet, it does remind me of many old family photos I''ve seen....they always seem stiff to me also.....rating this a 8</td>', 'I like the idea, but I feel the softness doesn''t convey much softness....it conveys stiffness and hardness to me.....yet, it does remind me of many old family photos I''ve seen....they always seem stiff to me also.....rating this a 8', '2004-06-30 15:15:38.000000', NULL, 1),
(787410, 86167, 14593, '<td valign="top">nice photo.....I love the muted colors and softness</td>', 'nice photo.....I love the muted colors and softness', '2004-06-30 15:16:36.000000', NULL, 1),
(787413, 86130, 14593, '<td valign="top">I like this!   I like the soft photos, but I also like the photos that show a different side to someone....</td>', 'I like this!   I like the soft photos, but I also like the photos that show a different side to someone....', '2004-06-30 15:17:49.000000', NULL, 1),
(787414, 85265, 14593, '<td valign="top">nice lighting and mood to this photograph</td>', 'nice lighting and mood to this photograph', '2004-06-30 15:18:05.000000', NULL, 1),
