(787492, 86277, 11895, '<td valign="top">very good protrait but needs a lighter background, the side and top of his head have lost all definition where they blend with the bg color</td>', 'very good protrait but needs a lighter background, the side and top of his head have lost all definition where they blend with the bg color', '2004-06-30 15:50:39.000000', NULL, 1),
(787493, 85972, 9821, '<td valign="top">Very pretty model. The whites of her eyes look a little overdone, but not too bad. Good light.</td>', 'Very pretty model. The whites of her eyes look a little overdone, but not too bad. Good light.', '2004-06-30 15:50:52.000000', NULL, 1),
