(795265, 85241, 10768, '<td valign="top">Very nice composition.  Her eyes grab all of the attention.  This is one of my favorites in this challenge.</td>', 'Very nice composition.  Her eyes grab all of the attention.  This is one of my favorites in this challenge.', '2004-07-04 18:16:57.000000', NULL, 1),
(795268, 85855, 10768, '<td valign="top">Very nice expression and pose.</td>', 'Very nice expression and pose.', '2004-07-04 18:19:11.000000', NULL, 1),
(795272, 85865, 10768, '<td valign="top">The pose has a very natural feel to it.  Well done.</td>', 'The pose has a very natural feel to it.  Well done.', '2004-07-04 18:23:45.000000', NULL, 1),
